package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.Room;import com.makemytrip.makemytrip.repositories.RoomRepository;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.FindAndModifyOptions;import org.springframework.data.mongodb.core.query.*;import org.springframework.stereotype.Service;import java.util.List;
@Service public class RoomService {private final RoomRepository rooms;private final MongoTemplate mongo;public RoomService(RoomRepository r,MongoTemplate m){rooms=r;mongo=m;}public List<Room> list(String hotelId){return rooms.findByHotelId(hotelId);}public Room save(String hotelId,Room room){room.setHotelId(hotelId);return rooms.save(room);}public Room claim(String hotel,String type){return claim(hotel,type,1);}public Room claim(String hotel,String type,int quantity){if(quantity<1)return null;Query q=new Query(Criteria.where("hotelId").is(hotel).and("roomType").is(type).and("availableQuantity").gte(quantity));return mongo.findAndModify(q,new Update().inc("availableQuantity",-quantity),FindAndModifyOptions.options().returnNew(true),Room.class);}public void release(String roomId){release(roomId,1);}public void release(String roomId,int quantity){if(quantity>0)mongo.updateFirst(new Query(Criteria.where("_id").is(roomId)),new Update().inc("availableQuantity",quantity),Room.class);}}
